// Immediate, visible handedness presets; the Controls editor still offers free positioning.
function handSwitchHTML(compact=false){const hand=cleanControls(profile.controls).hand;return `<section class="control-hand-switch ${compact?'compact':''}" role="group" aria-label="Choose left-handed or right-handed controls"><span>${compact?'CONTROLS':'Choose your control layout'}</span><div><button data-switch-hand="left" aria-pressed="${hand==='left'}" title="Joystick on the right, attacks on the left">Left-handed</button><button data-switch-hand="right" aria-pressed="${hand==='right'}" title="Joystick on the left, attacks on the right">Right-handed</button></div>${compact?'':'<small>Left-handed: move right, attack left. Right-handed: move left, attack right. Use Controls for custom placement.</small>'}</section>`}
function refreshHandSwitch(){const hand=cleanControls(profile.controls).hand;document.querySelectorAll('[data-switch-hand]').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.switchHand===hand))});document.body.dataset.controlHand=hand}
function switchControlHand(hand){if(!['left','right'].includes(hand))return;profile.controls=defaultControls(hand);resetControls();save();applyBattleControls();refreshHandSwitch();toast(hand==='left'?'Left-handed: joystick right, attack buttons left.':'Right-handed: joystick left, attack buttons right.')}
const battleHandSwitch=startArena;startArena=function(subject){battleHandSwitch(subject);document.querySelector('.battle-top')?.insertAdjacentHTML('beforeend',handSwitchHTML(true));refreshHandSwitch();applyBattleControls()};
const updateHandLayout=applyBattleControls;applyBattleControls=function(){updateHandLayout();refreshHandSwitch()};
document.addEventListener('click',event=>{const button=event.target.closest('button[data-switch-hand]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();switchControlHand(button.dataset.switchHand)},true);
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');refreshHandSwitch();
